	@Test
	void medicalQ7PlacementVariantsRenderRequestedInputOrder() throws Exception {
		Method method = ThemeQueryPlanRunBenchmark.BaseState.class.getDeclaredMethod("queryForVariant", Theme.class,
				int.class, String.class);
		method.setAccessible(true);

		String valuesTop = (String) method.invoke(null, Theme.MEDICAL_RECORDS, 7, "values-top-type-code");
		String typeFirst = (String) method.invoke(null, Theme.MEDICAL_RECORDS, 7, "type-values-code");
		String codeFirst = (String) method.invoke(null, Theme.MEDICAL_RECORDS, 7, "values-code-type");
		String antiBeforeValues = (String) method.invoke(null, Theme.MEDICAL_RECORDS, 7, "type-anti-values-code");
		String codeAntiBeforeType = (String) method.invoke(null, Theme.MEDICAL_RECORDS, 7, "values-code-anti-type");

		assertOrder(valuesTop, "VALUES ?code", "?med a med:Medication", "?med med:code ?code");
		assertOrder(typeFirst, "?med a med:Medication", "VALUES ?code", "?med med:code ?code");
		assertOrder(codeFirst, "VALUES ?code", "?med med:code ?code", "?med a med:Medication");
		assertOrder(antiBeforeValues, "?med a med:Medication", "FILTER NOT EXISTS", "VALUES ?code");
		assertOrder(antiBeforeValues, "FILTER NOT EXISTS", "VALUES ?code", "?med med:code ?code");
		assertOrder(codeAntiBeforeType, "VALUES ?code", "?med med:code ?code", "FILTER NOT EXISTS");
		assertOrder(codeAntiBeforeType, "FILTER NOT EXISTS", "?med a med:Medication", "FILTER EXISTS");
	}

	@Test
	void socialQ5VariantsRenderCandidateOrders() throws Exception {
		Method method = ThemeQueryPlanRunBenchmark.BaseState.class.getDeclaredMethod("queryForVariant", Theme.class,
				int.class, String.class);
		method.setAccessible(true);

		String nameBeforeUnion = (String) method.invoke(null, Theme.SOCIAL_MEDIA, 5,
				"social-q5-name-before-union");
		String branchLocalName = (String) method.invoke(null, Theme.SOCIAL_MEDIA, 5,
				"social-q5-branch-local-name");
		String existsName = (String) method.invoke(null, Theme.SOCIAL_MEDIA, 5,
				"social-q5-filter-exists-name");

		assertOrder(nameBeforeUnion, "VALUES ?u", "VALUES ?optName", "?u social:name ?optName");
		assertOrder(nameBeforeUnion, "?u social:name ?optName", "?u social:follows ?v", "?post social:authored ?u");
		assertOrder(branchLocalName, "VALUES ?u", "?u social:name ?optName", "?u social:follows ?v");
		assertOrder(branchLocalName, "VALUES ?u", "?u social:name ?optName", "?post social:authored ?u");
		assertOrder(existsName, "VALUES ?u", "FILTER EXISTS", "?u social:follows ?v");
	}

	@Test
	void uncachedPlanningVariableRenamingPreservesNonVariableLexicalForms() throws Exception {
		Method method = ThemeQueryPlanRunBenchmark.class.getDeclaredMethod("alphaRenameVariables", String.class,
				long.class);
		method.setAccessible(true);
		String source = "SELECT ?subject $object WHERE {\n"
				+ "  ?subject <urn:predicate?inside> $object .\n"
				+ "  BIND(\"?literal\" AS ?label) # ?comment\n"
				+ "  BIND('''$longLiteral''' AS $other)\n"
				+ "}";

		String renamed = (String) method.invoke(null, source, 41L);

		assertTrue(renamed.contains("SELECT ?subject__uncached41 $object__uncached41"), renamed);
		assertTrue(renamed.contains("?subject__uncached41 <urn:predicate?inside> $object__uncached41"), renamed);
		assertTrue(renamed.contains("\"?literal\" AS ?label__uncached41"), renamed);
		assertTrue(renamed.contains("# ?comment"), renamed);
		assertTrue(renamed.contains("'''$longLiteral''' AS $other__uncached41"), renamed);
	}

	private static void setTheme(ThemeQueryPlanRunBenchmark.BaseState state, Theme theme)
			throws ReflectiveOperationException {
		Field field = ThemeQueryPlanRunBenchmark.BaseState.class.getDeclaredField("theme");
		field.setAccessible(true);
		field.set(state, theme);
	}

	private static void assertOrder(String query, String first, String second, String third) {
		int firstIndex = query.indexOf(first);
		int secondIndex = query.indexOf(second);
		int thirdIndex = query.indexOf(third);
		assertTrue(firstIndex >= 0, query);
		assertTrue(secondIndex > firstIndex, query);
		assertTrue(thirdIndex > secondIndex, query);
	}
